import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.D7WGirly.js";const g=JSON.parse('{"title":"Dashboard — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"dashboard-02-how-tos-and-workflows.md","filePath":"dashboard-02-how-tos-and-workflows.md"}'),n={name:"dashboard-02-how-tos-and-workflows.md"};function i(s,e,l,h,d,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="dashboard-—-how-tos-workflows" tabindex="-1">Dashboard — How-tos &amp; Workflows <a class="header-anchor" href="#dashboard-—-how-tos-workflows" aria-label="Permalink to &quot;Dashboard — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Reading and navigating the Dashboard effectively</em></p><hr><h2 id="orienting-yourself-after-returning" tabindex="-1">Orienting Yourself After Returning <a class="header-anchor" href="#orienting-yourself-after-returning" aria-label="Permalink to &quot;Orienting Yourself After Returning&quot;">​</a></h2><p>When you log in or return to Lodestone after some time away, the Dashboard shows you what changed. Look for:</p><ol><li>The total new-item count in the top bar — this tells you how many items are new since your last visit</li><li>The cyan badge on each column header — shows how many new items are in that column</li><li>Cyan-highlighted rows within columns — these are the new items</li></ol><p>Start with the column most relevant to your current work. If you&#39;ve been heads-down on delivery, check <strong>Executing Plans</strong> first. If you had transcripts running, check <strong>Collecting Data</strong>.</p><hr><h2 id="navigating-to-an-object" tabindex="-1">Navigating to an Object <a class="header-anchor" href="#navigating-to-an-object" aria-label="Permalink to &quot;Navigating to an Object&quot;">​</a></h2><p>Every row in the Dashboard is a link. Clicking any item takes you directly to that object in its native module:</p><ul><li>A Feature row → Feature detail page</li><li>A Roadmap row → Roadmap editor</li><li>A PRD row → the PRD document for that Feature</li><li>An Export row → the source artifact (Roadmap, Strategy, etc.)</li><li>A Release Board row → the Release Kanban board</li></ul><p>The Dashboard is a jumpboard — it surfaces the most recently touched objects across your workspace and lets you get to them in one click.</p><hr><h2 id="identifying-stale-exports-in-the-aligning-column" tabindex="-1">Identifying Stale Exports in the Aligning Column <a class="header-anchor" href="#identifying-stale-exports-in-the-aligning-column" aria-label="Permalink to &quot;Identifying Stale Exports in the Aligning Column&quot;">​</a></h2><p>The <strong>Aligning Plans</strong> column tracks every export and shared snapshot your team has sent. If a Roadmap or Strategy has been updated since it was last exported, a <strong>&quot;Newer version available&quot;</strong> warning appears on that row.</p><p>This is a signal to reshare. The stakeholders who received the old version may be looking at an outdated picture. Click through to the source artifact and re-export.</p><blockquote><p><strong>Use case:</strong> Before a stakeholder meeting, scan the Aligning column. If any shared artifacts show &quot;Newer version available,&quot; update them before the meeting starts.</p></blockquote><hr><h2 id="reordering-columns" tabindex="-1">Reordering Columns <a class="header-anchor" href="#reordering-columns" aria-label="Permalink to &quot;Reordering Columns&quot;">​</a></h2><p>Drag any column header to rearrange the order of the five columns. The layout adjusts immediately. Use this to bring your most-used columns to the left where they&#39;re easier to scan.</p><p>To drag: click and hold the column header, then drag it to a new position.</p><hr><h2 id="reading-feature-keys" tabindex="-1">Reading Feature Keys <a class="header-anchor" href="#reading-feature-keys" aria-label="Permalink to &quot;Reading Feature Keys&quot;">​</a></h2><p>Backlog items show their unique feature key (e.g. FEAT-7) below the item title. These keys are persistent identifiers — they appear in the backlog, in exports, and in integrations. You can use these keys to reference specific features in Copilot (&quot;update FEAT-7 to Completed&quot;) or in conversations with your team.</p><hr><p><em>Next: Advanced Features &amp; Customization — understanding what each column contains and how to use the Dashboard as a daily planning tool.</em></p>',26)])])}const m=a(n,[["render",i]]);export{g as __pageData,m as default};
